import{_ as a,o as t,c as o,a6 as r}from"./chunks/framework.De615z8S.js";const f=JSON.parse('{"title":"Shopify横幅：桌面与手机分别排版","description":"","frontmatter":{"id":"shopify-hero","title":"Shopify横幅：桌面与手机分别排版","chapter":"03","topic":"cross-border","status":"已公开","evidence_status":"原创教程与规划示范，尚未执行图像任务或后台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","kv-marketing-workflow","ad-production-kit"],"platform_rule_ids":["shopify"],"order":23.4},"headers":[],"relativePath":"ecommerce/shopify-hero.md","filePath":"ecommerce/shopify-hero.md"}'),i={name:"ecommerce/shopify-hero.md"};function h(s,e,d,p,l,n){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="shopify横幅-桌面与手机分别排版" tabindex="-1">Shopify横幅：桌面与手机分别排版 <a class="header-anchor" href="#shopify横幅-桌面与手机分别排版" aria-label="Permalink to &quot;Shopify横幅：桌面与手机分别排版&quot;">​</a></h1><p>先确定具体主题、区块和文字呈现方式。同一个背景在桌面留白充足，到了手机可能只剩商品一角；所以横幅不能只做等比缩小。</p><h2 id="第1步-记录区块条件" tabindex="-1">第1步：记录区块条件 <a class="header-anchor" href="#第1步-记录区块条件" aria-label="Permalink to &quot;第1步：记录区块条件&quot;">​</a></h2><p>登记区块是否支持桌面／手机不同素材，图片焦点、覆盖文字、按钮与容器高度如何设置。拿当前主题的实际预览判断；“所有Shopify横幅都用同一个尺寸”不是可靠的交付要求。</p><p>练习先做桌面2400×1200、手机1200×1600两个构图稿，均是本教程的设计建议，不是平台统一规格。实际区块不支持双素材时，制作可兼容裁切的母版并记录取舍。</p><h2 id="第2步-准备两份构图简报" tabindex="-1">第2步：准备两份构图简报 <a class="header-anchor" href="#第2步-准备两份构图简报" aria-label="Permalink to &quot;第2步：准备两份构图简报&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>DN01练习构图</th><th>检查重点</th></tr></thead><tbody><tr><td>桌面</td><td>商品在右侧，左侧留给原生标题和按钮</td><td>完整主体、文字区对比与留白</td></tr><tr><td>手机</td><td>商品放在中下部，上方留给短标题</td><td>主体不被裁、按钮不遮关键结构</td></tr></tbody></table><p>使用<a href="/ai-visual-creation-handbook/prompts/P14">P14双尺寸横幅</a>。底图先不画标题、按钮和促销信息；准确文字交给主题或图层排版。英文示例“Make room for everyday essentials”是创作文案，不是“节省多少空间”的事实承诺。</p><h2 id="第3步-先做底图再排版" tabindex="-1">第3步：先做底图再排版 <a class="header-anchor" href="#第3步-先做底图再排版" aria-label="Permalink to &quot;第3步：先做底图再排版&quot;">​</a></h2><p>商品来自真实实拍，桌面道具只作背景，避免暗示随商品发货。匹配光向与接触阴影，不改变盒体。手机稿重新摆主体和背景，不从桌面稿中心裁一刀交付。</p><p>必要时用<a href="/ai-visual-creation-handbook/prompts/P06">P06</a>只调整背景或留白。生成工具如果只支持近似比例，先保存实际底图，再在图层画布里裁切或扩背景，报告最终实际像素。</p><h2 id="第4步-四个场景预览" tabindex="-1">第4步：四个场景预览 <a class="header-anchor" href="#第4步-四个场景预览" aria-label="Permalink to &quot;第4步：四个场景预览&quot;">​</a></h2><p>检查桌面宽屏、平板、手机和集合／首页实际位置。文字与按钮另有自己的布局条件，不能只看图片文件。导出文件、源文件和已预览区块分别列清楚；“PNG已完成”不等于“主题已配置”。</p><p>上传限制与色彩处理见<a href="https://help.shopify.com/en/manual/online-store/images/theme-images" target="_blank" rel="noreferrer">Shopify官方图片说明</a>。没有做真实商店预览时保留待验证状态。</p>',14)])])}const m=a(i,[["render",h]]);export{f as __pageData,m as default};
